INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_oldtable_0713', 'cpu_岗位_06', '翻到一张旧岗位表截图，说两个数据治理岗都能报', '群里传的截图，看水印是2024年的老岗位表，那会儿 NL-14380 的专业要求写得比较宽。但今年的岗位表和后来的补充公告都改了，数据治理方向单独列了列名。截图没有补充公告的部分，别拿这个当依据，还是去官网查现行版本吧。', '备考', '["公务员", "岗位表", "专业目录"]', '[]', 212, 32, 7, 5012, '2025-07-13T12:00:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_000_702', 'cpu_云台_08', '协议保过班到底靠不靠谱（2024 年更新）', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（24 届，三战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "行测", "岗位表", "综合管理类"]', '[]', 1603, 177, 0, 11797, '2026-05-11T15:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_001_292', 'cpu_应届_10', '毕业季和备考撞在一起怎么办', '答辩、实习、离校手续、考试全挤在3月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。', '备考', '["公务员", "行测", "资格复审"]', '[]', 0, 0, 3, 0, '2025-07-22T23:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_002_124', 'cpu_面试_07', '资格复审要准备的材料清单', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的3个月期限差点不够用。（更新：换岗位了。）', '备考', '["资格复审", "申论", "面试"]', '[]', 2249, 649, 35, 50474, '2025-07-09T13:55:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_003_167', 'cpu_基层_11', '相近专业能不能报，我踩过的坑（2024 年更新）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（25 届，三战。）有问题评论区问，看到就回。', '备考', '["综合管理类", "岗位表", "行测"]', '[]', 0, 0, 40, 0, '2026-06-08T17:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_004_498', 'cpu_面试_07', '准考证打印那几天的注意事项｜二战总结', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打32份备用，考场丢了没地方补。（24 届，三战。）', '备考', '["省考", "岗位表"]', '[]', 1577, 126, 0, 57118, '2026-05-02T17:57:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_005_112', 'cpu_面试_07', '怎么分辨押题命中率的水分', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。', '备考', '["面试", "公务员", "省考"]', '[]', 1676, 359, 15, 58026, '2026-07-04T18:55:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_006_122', 'cpu_备考_05', '考场能带什么不能带什么（2026 年更新）', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。（评论区有 22 条追问我统一回在这里了。）有问题评论区问，看到就回。', '备考', '["申论", "省考"]', '[]', 817, 268, 46, 19228, '2026-06-15T10:21:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_007_235', 'cpu_上岸_00', '岗位表和补充公告不一致的时候听谁的', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。', '备考', '["行测", "面试"]', '[]', 327, 63, 4, 3827, '2026-06-07T18:55:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_008_852', 'cpu_基层_11', '考前一晚睡不着的解决办法', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨2点还醒着，第二天资料分析基本是蒙的。（更新：差几分。）以上仅是个人经历，具体以官方公告为准。', '备考', '["行测", "公务员"]', '[]', 1698, 256, 14, 54015, '2025-07-19T13:00:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_009_773', 'cpu_pool_012', '成绩复核申请是怎么回事（2025 年更新）', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后60个工作日内提交书面材料，过期不受理。不接广告，不推荐机构。', '备考', '["公务员", "申论"]', '[]', 638, 175, 0, 13551, '2025-07-28T14:21:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_010_815', 'cpu_云台_08', '跟家里怎么沟通考公这件事｜二战总结', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。（评论区有 10 条追问我统一回在这里了。）以上仅是个人经历，具体以官方公告为准。', '备考', '["专业目录", "资格复审", "应届生", "行测"]', '[]', 0, 0, 11, 0, '2026-06-11T13:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_011_938', 'cpu_行测_03', '考前一晚睡不着的解决办法｜南岭省', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨4点还醒着，第二天资料分析基本是蒙的。（评论区有 25 条追问我统一回在这里了。）以上仅是个人经历，具体以官方公告为准。', '备考', '["面试", "避坑", "省考", "行测"]', '[]', 912, 49, 62, 33798, '2025-07-18T13:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_012_860', 'cpu_pool_022', '那些说有内部题的，我劝你别碰', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。有问题评论区问，看到就回。', '备考', '["专业目录", "公务员", "面试", "避坑"]', '[]', 1694, 416, 27, 25487, '2026-05-23T09:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_013_352', 'cpu_备考_05', '相近专业能不能报，我踩过的坑', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。', '备考', '["备考经验", "省考", "综合管理类"]', '[]', 1560, 110, 0, 30746, '2026-05-24T09:56:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_014_707', 'cpu_pool_010', '在职备考怎么挤时间', '通勤路上听音频，午休做16道题，晚上留2小时集中攻一个模块。关键是别追求每天学很久，而是别断。我断过一周，回来手感全没了。', '备考', '["避坑", "面试", "备考经验", "省考"]', '[]', 321, 54, 43, 9570, '2026-06-17T12:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_015_950', 'cpu_上岸_00', '相近专业能不能报，我踩过的坑（更新版）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（评论区有 24 条追问我统一回在这里了。）后续有变化我再更新。', '备考', '["避坑", "面试", "综合管理类", "备考经验"]', '[]', 662, 103, 0, 14862, '2026-07-03T09:32:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_016_505', 'cpu_基层_11', '相近专业能不能报，我踩过的坑（更新版）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。', '备考', '["综合管理类", "公务员", "行测"]', '[]', 586, 56, 1, 21039, '2026-06-04T13:17:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_017_698', 'cpu_岗位_06', '在职备考怎么挤时间（补充）', '通勤路上听音频，午休做34道题，晚上留3小时集中攻一个模块。关键是别追求每天学很久，而是别断。我断过一周，回来手感全没了。（我报的是 NL-14263，情况可能跟你不一样。）以上仅是个人经历，具体以官方公告为准。', '备考', '["综合管理类", "行测", "公务员", "资格复审"]', '[]', 0, 0, 40, 0, '2025-07-10T21:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_018_111', 'cpu_行测_03', '申论到底怎么提分', '找了老师批改46篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。（更新：差几分。）后续有变化我再更新。', '备考', '["避坑", "专业目录", "面试"]', '[]', 0, 0, 0, 0, '2026-07-06T08:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_019_388', 'cpu_公考_01', '怎么分辨押题命中率的水分｜应届生视角', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。后续有变化我再更新。', '备考', '["省考", "综合管理类", "专业目录", "备考经验"]', '[]', 1225, 253, 0, 28262, '2026-06-27T13:25:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_020_797', 'cpu_基层_11', '成绩复核申请是怎么回事', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后76个工作日内提交书面材料，过期不受理。（25 届，三战。）不接广告，不推荐机构。', '备考', '["行测", "避坑", "综合管理类", "申论"]', '[]', 1573, 359, 88, 23105, '2026-06-16T12:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_021_583', 'cpu_行测_03', '三个月上岸的复习节奏（附时间表）', '我是6月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天8小时，其中资料分析固定39分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（25 届，三战。）', '备考', '["备考经验", "资格复审", "申论", "岗位表"]', '[]', 1022, 178, 63, 12400, '2025-07-13T13:46:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_022_351', 'cpu_岗位_06', '资料分析提速的几个笨办法', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了40天，从每题75秒降到41秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。以上仅是个人经历，具体以官方公告为准。', '备考', '["面试", "申论"]', '[]', 142, 22, 0, 4392, '2026-06-08T17:50:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_023_736', 'cpu_备考_05', '相近专业能不能报，我踩过的坑（答疑整理）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（26 届，一战。）', '备考', '["行测", "岗位表", "备考经验", "申论"]', '[]', 0, 0, 40, 0, '2026-06-24T11:23:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_024_141', 'cpu_pool_013', '专业名字带「数据」的到底能报哪些岗位｜长文', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2024年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（评论区有 25 条追问我统一回在这里了。）', '备考', '["行测", "专业目录", "备考经验", "面试"]', '[]', 456, 56, 0, 15326, '2026-06-20T20:06:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_025_777', 'cpu_基层_11', '考前一晚睡不着的解决办法｜云台区', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨3点还醒着，第二天资料分析基本是蒙的。（写于笔试前 61 天。）以上仅是个人经历，具体以官方公告为准。', '备考', '["应届生", "岗位表", "申论"]', '[]', 0, 0, 10, 0, '2026-05-21T10:29:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_026_110', 'cpu_基层_11', '毕业季和备考撞在一起怎么办（续）', '答辩、实习、离校手续、考试全挤在7月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（写于笔试前 27 天。）后续有变化我再更新。', '备考', '["面试", "资格复审", "行测"]', '[]', 2131, 215, 0, 12994, '2025-07-19T20:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_027_936', 'cpu_面试_07', '资料分析提速的几个笨办法｜南岭省', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了21天，从每题93秒降到50秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。有问题评论区问，看到就回。', '备考', '["申论", "面试", "避坑"]', '[]', 0, 0, 26, 0, '2026-06-28T08:25:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_028_976', 'cpu_面试_07', '资料分析提速的几个笨办法（补充）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了40天，从每题90秒降到53秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（我报的是 NL-14477，情况可能跟你不一样。）有问题评论区问，看到就回。', '备考', '["备考经验", "避坑"]', '[]', 1038, 281, 70, 15590, '2026-06-10T12:52:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_029_464', 'cpu_岗位_06', '那些说有内部题的，我劝你别碰｜慎入', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。以上仅是个人经历，具体以官方公告为准。', '备考', '["资格复审", "公务员", "省考"]', '[]', 542, 39, 46, 6195, '2025-07-08T11:35:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_030_647', 'cpu_应届_10', '有人卖面试内部名单，这事性质很严重｜南岭省', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。转载请注明出处。', '备考', '["综合管理类", "备考经验"]', '[]', 346, 83, 0, 7928, '2025-07-14T20:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_031_942', 'cpu_面试_07', '有人卖面试内部名单，这事性质很严重｜干货', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（23 届，一战。）不接广告，不推荐机构。', '备考', '["资格复审", "省考", "面试"]', '[]', 141, 36, 0, 4933, '2026-06-14T22:31:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_032_945', 'cpu_面试_07', '协议保过班到底靠不靠谱', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "申论", "避坑"]', '[]', 239, 14, 0, 8364, '2026-06-08T07:39:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_033_290', 'cpu_公考_09', '考前一晚睡不着的解决办法｜踩坑实录', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨1点还醒着，第二天资料分析基本是蒙的。（我报的是 NL-14308，情况可能跟你不一样。）', '备考', '["行测", "岗位表", "省考"]', '[]', 86, 25, 0, 3157, '2026-05-20T10:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_034_646', 'cpu_申论_02', '相近专业能不能报，我踩过的坑（2024 年更新）（续）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。有问题评论区问，看到就回。', '备考', '["专业目录", "资格复审"]', '[]', 0, 0, 41, 0, '2026-06-23T12:50:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_035_402', 'cpu_公考_09', '岗位表和补充公告不一致的时候听谁的（补充）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（我报的是 NL-14401，情况可能跟你不一样。）不接广告，不推荐机构。', '备考', '["专业目录", "避坑"]', '[]', 327, 55, 4, 2245, '2026-06-04T14:35:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_036_954', 'cpu_政务_04', '那些说有内部题的，我劝你别碰｜上岸后回看', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。', '备考', '["公务员", "行测", "应届生"]', '[]', 831, 243, 0, 32910, '2026-05-23T13:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_037_306', 'cpu_申论_02', '申论到底怎么提分（答疑整理）', '找了老师批改55篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。（更新：进面了。）', '备考', '["公务员", "应届生", "省考", "避坑"]', '[]', 100, 19, 0, 951, '2026-06-11T15:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_038_764', 'cpu_基层_11', '资格复审要准备的材料清单｜综合管理类', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的6个月期限差点不够用。（写于笔试前 62 天。）', '备考', '["面试", "行测", "综合管理类"]', '[]', 0, 0, 39, 0, '2026-05-02T11:23:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_039_349', 'cpu_岗位_06', '考场能带什么不能带什么｜上岸后回看', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。（25 届，一战。）转载请注明出处。', '备考', '["申论", "综合管理类"]', '[]', 0, 0, 14, 0, '2026-06-06T21:29:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_040_274', 'cpu_应届_10', '专业目录读起来为什么这么费劲｜在职考生视角', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。（评论区有 11 条追问我统一回在这里了。）', '备考', '["应届生", "申论", "岗位表", "行测"]', '[]', 133, 10, 0, 4347, '2026-05-01T08:10:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_041_341', 'cpu_pool_020', '相近专业能不能报，我踩过的坑｜综合管理类', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（更新：弃考了。）', '备考', '["面试", "备考经验", "省考", "岗位表"]', '[]', 347, 90, 86, 13499, '2026-05-15T20:43:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_042_313', 'cpu_备考_05', '申论到底怎么提分（续）', '找了老师批改41篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。', '备考', '["岗位表", "申论", "省考", "避坑"]', '[]', 1130, 317, 13, 10588, '2026-05-25T20:20:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_043_915', 'cpu_面试_07', '有人卖面试内部名单，这事性质很严重（2024 年更新）', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。有问题评论区问，看到就回。', '备考', '["省考", "资格复审"]', '[]', 317, 71, 23, 7613, '2026-06-05T13:18:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_044_489', 'cpu_pool_022', '毕业季和备考撞在一起怎么办（2025 年更新）', '答辩、实习、离校手续、考试全挤在7月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（更新：已上岸。）后续有变化我再更新。', '备考', '["省考", "公务员", "行测", "资格复审"]', '[]', 740, 187, 7, 25713, '2026-07-04T08:52:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_045_108', 'cpu_备考_05', '三个月上岸的复习节奏（附时间表）（2024 年更新）', '我是4月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天9小时，其中资料分析固定24分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（写于笔试前 61 天。）以上仅是个人经历，具体以官方公告为准。', '备考', '["资格复审", "申论"]', '[]', 950, 316, 2, 8894, '2026-07-01T12:00:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_046_101', 'cpu_云台_08', '资料分析提速的几个笨办法（2026 年更新）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了62天，从每题150秒降到50秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（评论区有 2 条追问我统一回在这里了。）', '备考', '["行测", "申论"]', '[]', 984, 66, 53, 35039, '2026-06-16T07:44:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_047_407', 'cpu_面试_07', '毕业季和备考撞在一起怎么办（第二篇）', '答辩、实习、离校手续、考试全挤在3月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。后续有变化我再更新。', '备考', '["应届生", "行测"]', '[]', 459, 96, 23, 10036, '2026-06-21T09:19:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_048_755', 'cpu_政务_04', '落榜之后我调整了两个月（2024 年更新）', '第一年差2.2分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。不接广告，不推荐机构。', '备考', '["专业目录", "综合管理类", "岗位表"]', '[]', 789, 150, 0, 21436, '2025-07-21T10:31:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_049_417', 'cpu_备考_05', '协议保过班到底靠不靠谱（2026 年更新）', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（评论区有 10 条追问我统一回在这里了。）不接广告，不推荐机构。', '备考', '["专业目录", "资格复审", "综合管理类", "备考经验"]', '[]', 918, 257, 24, 22424, '2026-06-05T16:26:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_050_753', 'cpu_云台_08', '落榜之后我调整了两个月｜干货', '第一年差1.2分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。后续有变化我再更新。', '备考', '["省考", "岗位表", "资格复审"]', '[]', 310, 29, 23, 5990, '2025-07-19T10:31:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_051_173', 'cpu_政务_04', '准考证打印那几天的注意事项｜南岭省', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打10份备用，考场丢了没地方补。（写于笔试前 67 天。）有问题评论区问，看到就回。', '备考', '["岗位表", "专业目录", "综合管理类"]', '[]', 0, 0, 27, 0, '2026-05-16T23:33:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_052_276', 'cpu_公考_01', '考前一晚睡不着的解决办法（2025 年更新）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨1点还醒着，第二天资料分析基本是蒙的。（我报的是 NL-14477，情况可能跟你不一样。）有问题评论区问，看到就回。', '备考', '["申论", "行测", "备考经验", "省考"]', '[]', 67, 13, 0, 1128, '2026-05-27T10:49:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_053_608', 'cpu_应届_10', '申论到底怎么提分｜应届生视角', '找了老师批改40篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "行测"]', '[]', 592, 145, 13, 10697, '2026-05-25T21:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_054_852', 'cpu_pool_001', '专业名字带「数据」的到底能报哪些岗位', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2025年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（写于笔试前 55 天。）', '备考', '["避坑", "备考经验"]', '[]', 645, 152, 20, 21210, '2026-07-01T11:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_055_806', 'cpu_应届_10', '相近专业能不能报，我踩过的坑｜长文', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（更新：进面了。）转载请注明出处。', '备考', '["专业目录", "备考经验", "资格复审", "公务员"]', '[]', 0, 0, 32, 0, '2026-06-03T14:45:00+08:00');
