INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_057_746', 'cpu_基层_11', '毕业季和备考撞在一起怎么办（2025 年更新）（补充）', '答辩、实习、离校手续、考试全挤在6月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（评论区有 29 条追问我统一回在这里了。）', '备考', '["资格复审", "避坑"]', '[]', 1588, 401, 37, 48819, '2026-06-09T14:03:00+08:00');
