INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_059_466', 'cpu_公考_01', '模考成绩波动大是正常的吗', '正常。我模考分数从113到134都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。有问题评论区问，看到就回。', '备考', '["避坑", "省考"]', '[]', 0, 0, 0, 0, '2026-06-21T18:00:00+08:00');
