INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_066_761', 'cpu_上岸_00', '三个月上岸的复习节奏（附时间表）｜干货', '我是8月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天3小时，其中资料分析固定49分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。以上仅是个人经历，具体以官方公告为准。', '备考', '["行测", "应届生", "资格复审"]', '[]', 62, 12, 0, 1732, '2026-06-09T09:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_067_279', 'cpu_应届_10', '申论到底怎么提分｜慎入', '找了老师批改14篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。后续有变化我再更新。', '备考', '["备考经验", "岗位表"]', '[]', 111, 29, 0, 1584, '2026-06-06T17:34:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_068_386', 'cpu_云台_08', '落榜之后我调整了两个月｜数据治理岗', '第一年差8.2分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。转载请注明出处。', '备考', '["面试", "综合管理类"]', '[]', 1216, 89, 49, 30450, '2026-06-27T17:04:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_069_237', 'cpu_pool_016', '考前一晚睡不着的解决办法（2025 年更新）（补充）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨3点还醒着，第二天资料分析基本是蒙的。（写于笔试前 8 天。）', '备考', '["面试", "避坑"]', '[]', 1134, 331, 47, 34477, '2025-07-15T17:55:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_070_753', 'cpu_应届_10', '相近专业能不能报，我踩过的坑｜数据治理岗', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（更新：换岗位了。）', '备考', '["公务员", "资格复审"]', '[]', 831, 72, 0, 13498, '2026-06-15T11:35:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_071_881', 'cpu_pool_009', '资料分析提速的几个笨办法｜踩坑实录', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了58天，从每题119秒降到44秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（评论区有 14 条追问我统一回在这里了。）', '备考', '["面试", "省考"]', '[]', 2899, 366, 3, 103888, '2025-07-27T21:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_072_182', 'cpu_云台_08', '考前一晚睡不着的解决办法（2024 年更新）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨1点还醒着，第二天资料分析基本是蒙的。转载请注明出处。', '备考', '["避坑", "备考经验", "专业目录", "公务员"]', '[]', 0, 0, 40, 0, '2026-07-08T08:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_073_553', 'cpu_政务_04', '专业名字带「数据」的到底能报哪些岗位｜踩坑实录', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2024年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。', '备考', '["公务员", "省考", "行测"]', '[]', 962, 187, 0, 27092, '2025-07-24T17:15:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_074_494', 'cpu_公考_01', '三个月上岸的复习节奏（附时间表）｜干货（答疑整理）', '我是6月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天10小时，其中资料分析固定26分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。以上仅是个人经历，具体以官方公告为准。', '备考', '["综合管理类", "专业目录", "面试", "岗位表"]', '[]', 884, 97, 20, 22805, '2026-06-23T13:52:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_075_944', 'cpu_岗位_06', '资格复审要准备的材料清单（第二篇）', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的1个月期限差点不够用。', '备考', '["应届生", "专业目录"]', '[]', 1432, 279, 6, 31790, '2025-07-10T18:52:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_076_706', 'cpu_基层_11', '三个月上岸的复习节奏（附时间表）｜踩坑实录', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天9小时，其中资料分析固定34分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（更新：弃考了。）有问题评论区问，看到就回。', '备考', '["省考", "行测", "资格复审"]', '[]', 0, 0, 36, 0, '2025-07-19T09:06:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_077_864', 'cpu_公考_01', '考点提前踩点的几个建议', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2024年就吃过这个亏，差点迟到。', '备考', '["省考", "备考经验", "避坑", "资格复审"]', '[]', 0, 0, 24, 0, '2026-06-21T10:57:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_078_989', 'cpu_云台_08', '岗位表和补充公告不一致的时候听谁的｜云台区', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（我报的是 NL-14401，情况可能跟你不一样。）不接广告，不推荐机构。', '备考', '["岗位表", "专业目录", "避坑", "公务员"]', '[]', 0, 0, 0, 0, '2025-07-15T19:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_079_324', 'cpu_云台_08', '毕业季和备考撞在一起怎么办（2024 年更新）', '答辩、实习、离校手续、考试全挤在8月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（写于笔试前 71 天。）转载请注明出处。', '备考', '["综合管理类", "应届生"]', '[]', 835, 186, 44, 23004, '2026-06-14T16:21:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_080_389', 'cpu_pool_022', '落榜之后我调整了两个月（2024 年更新）（第二篇）', '第一年差3.3分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。不接广告，不推荐机构。', '备考', '["备考经验", "面试", "专业目录"]', '[]', 41, 2, 11, 1522, '2026-05-21T17:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_081_868', 'cpu_pool_002', '模考成绩波动大是正常的吗（补充）', '正常。我模考分数从107到135都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。（评论区有 14 条追问我统一回在这里了。）', '备考', '["行测", "省考"]', '[]', 406, 133, 53, 3471, '2026-06-25T13:56:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_082_326', 'cpu_政务_04', '成绩复核申请是怎么回事（2025 年更新）（更新版）', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后39个工作日内提交书面材料，过期不受理。', '备考', '["省考", "申论"]', '[]', 1322, 198, 60, 49428, '2025-07-22T10:50:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_083_644', 'cpu_云台_08', '申论到底怎么提分｜数据治理岗', '找了老师批改58篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。（24 届，三战。）有问题评论区问，看到就回。', '备考', '["备考经验", "岗位表"]', '[]', 3, 1, 43, 97, '2025-07-28T14:31:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_084_798', 'cpu_政务_04', '跟家里怎么沟通考公这件事｜二战总结（续）', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。', '备考', '["专业目录", "面试"]', '[]', 372, 44, 6, 9491, '2025-07-14T18:53:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_085_626', 'cpu_云台_08', '协议保过班到底靠不靠谱｜南岭省', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。后续有变化我再更新。', '备考', '["省考", "面试", "公务员"]', '[]', 384, 96, 0, 10499, '2026-06-07T12:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_086_909', 'cpu_pool_025', '专业名字带「数据」的到底能报哪些岗位（2024 年更新）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2024年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（评论区有 10 条追问我统一回在这里了。）后续有变化我再更新。', '备考', '["面试", "省考", "应届生", "资格复审"]', '[]', 208, 34, 6, 5426, '2026-05-20T22:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_087_317', 'cpu_申论_02', '机构说相近专业都能报，可信吗', '不可信。机构没有资格认定权，说了不作数。他们这么说是为了扩大招生面。以官方目录和招录单位书面答复为准，其他都是参考。不接广告，不推荐机构。', '备考', '["面试", "申论"]', '[]', 435, 71, 6, 9276, '2026-05-01T09:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_088_297', 'cpu_基层_11', '那些说有内部题的，我劝你别碰（续）', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。有问题评论区问，看到就回。', '备考', '["岗位表", "应届生"]', '[]', 395, 37, 0, 10278, '2026-06-08T16:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_089_415', 'cpu_应届_10', '机构说相近专业都能报，可信吗（第二篇）', '不可信。机构没有资格认定权，说了不作数。他们这么说是为了扩大招生面。以官方目录和招录单位书面答复为准，其他都是参考。（写于笔试前 37 天。）转载请注明出处。', '备考', '["岗位表", "综合管理类", "备考经验", "申论"]', '[]', 2404, 488, 0, 45877, '2026-07-07T15:44:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_090_603', 'cpu_应届_10', '资料分析提速的几个笨办法｜二战总结', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了77天，从每题137秒降到46秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（我报的是 NL-14356，情况可能跟你不一样。）以上仅是个人经历，具体以官方公告为准。', '备考', '["应届生", "公务员", "面试"]', '[]', 1116, 231, 37, 18426, '2026-05-01T16:29:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_091_929', 'cpu_pool_006', '专业目录读起来为什么这么费劲｜慎入', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。转载请注明出处。', '备考', '["省考", "行测", "避坑", "应届生"]', '[]', 1179, 359, 27, 31247, '2026-05-21T23:04:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_092_805', 'cpu_岗位_06', '考场能带什么不能带什么', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。（23 届，二战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "面试"]', '[]', 0, 0, 21, 0, '2026-07-05T20:08:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_093_438', 'cpu_行测_03', '模考成绩波动大是正常的吗｜综合管理类', '正常。我模考分数从125到135都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。（更新：换岗位了。）', '备考', '["应届生", "资格复审"]', '[]', 1239, 284, 0, 44849, '2026-05-11T08:12:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_094_389', 'cpu_行测_03', '准考证打印那几天的注意事项｜二战总结（第二篇）', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打41份备用，考场丢了没地方补。', '备考', '["岗位表", "资格复审", "面试", "公务员"]', '[]', 42, 9, 63, 966, '2025-07-26T10:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_095_350', 'cpu_公考_09', '专业名字带「数据」的到底能报哪些岗位（答疑整理）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2024年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（23 届，二战。）转载请注明出处。', '备考', '["资格复审", "综合管理类", "备考经验"]', '[]', 0, 0, 0, 0, '2025-07-15T17:00:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_096_607', 'cpu_政务_04', '资格复审要准备的材料清单（2026 年更新）', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的3个月期限差点不够用。', '备考', '["备考经验", "综合管理类"]', '[]', 761, 204, 0, 15829, '2026-05-22T08:25:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_097_867', 'cpu_公考_01', '落榜之后我调整了两个月｜上岸后回看', '第一年差4.8分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（我报的是 NL-14356，情况可能跟你不一样。）有问题评论区问，看到就回。', '备考', '["应届生", "专业目录"]', '[]', 0, 0, 0, 0, '2026-06-04T22:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_098_290', 'cpu_公考_09', '那些说有内部题的，我劝你别碰｜踩坑实录', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。', '备考', '["专业目录", "综合管理类", "申论", "资格复审"]', '[]', 492, 103, 40, 9147, '2026-06-28T14:53:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_099_961', 'cpu_公考_09', '落榜之后我调整了两个月（答疑整理）', '第一年差0.8分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。', '备考', '["岗位表", "公务员", "面试"]', '[]', 688, 100, 62, 26309, '2025-07-22T14:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_100_437', 'cpu_公考_01', '专业名字带「数据」的到底能报哪些岗位（更新版）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2025年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（更新：差几分。）', '备考', '["岗位表", "申论", "面试"]', '[]', 0, 0, 45, 0, '2025-07-26T07:14:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_101_417', 'cpu_云台_08', '考点提前踩点的几个建议（第二篇）', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2024年就吃过这个亏，差点迟到。以上仅是个人经历，具体以官方公告为准。', '备考', '["行测", "资格复审", "岗位表", "备考经验"]', '[]', 910, 195, 42, 25171, '2025-07-16T11:20:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_102_708', 'cpu_备考_05', '相近专业能不能报，我踩过的坑（续）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（写于笔试前 46 天。）', '备考', '["岗位表", "专业目录", "应届生"]', '[]', 1171, 162, 7, 26218, '2025-07-09T20:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_103_753', 'cpu_公考_09', '毕业季和备考撞在一起怎么办｜长文', '答辩、实习、离校手续、考试全挤在6月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（我报的是 NL-14356，情况可能跟你不一样。）', '备考', '["面试", "综合管理类"]', '[]', 402, 29, 64, 4087, '2025-07-20T13:33:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_104_614', 'cpu_备考_05', '模考成绩波动大是正常的吗（补充）', '正常。我模考分数从125到130都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。（25 届，三战。）', '备考', '["申论", "备考经验", "避坑", "专业目录"]', '[]', 0, 0, 48, 0, '2026-06-05T23:56:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_105_396', 'cpu_行测_03', '有人卖面试内部名单，这事性质很严重（2025 年更新）', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（写于笔试前 85 天。）以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "应届生", "行测", "资格复审"]', '[]', 2653, 622, 0, 43554, '2025-07-22T16:23:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_106_193', 'cpu_pool_001', '相近专业能不能报，我踩过的坑（2024 年更新）（第二篇）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。', '备考', '["申论", "专业目录", "行测", "应届生"]', '[]', 0, 0, 27, 0, '2025-07-25T10:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_107_735', 'cpu_公考_09', '落榜之后我调整了两个月｜长文', '第一年差8.2分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（评论区有 24 条追问我统一回在这里了。）', '备考', '["申论", "综合管理类", "岗位表"]', '[]', 0, 0, 45, 0, '2025-07-09T07:08:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_108_195', 'cpu_云台_08', '考前一晚睡不着的解决办法（答疑整理）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨1点还醒着，第二天资料分析基本是蒙的。（写于笔试前 81 天。）后续有变化我再更新。', '备考', '["资格复审", "岗位表", "省考"]', '[]', 677, 200, 0, 4494, '2026-05-07T17:08:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_109_676', 'cpu_公考_01', '考场能带什么不能带什么｜二战总结', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。（评论区有 26 条追问我统一回在这里了。）有问题评论区问，看到就回。', '备考', '["面试", "申论", "专业目录"]', '[]', 2578, 458, 31, 27955, '2026-06-12T20:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_110_179', 'cpu_pool_004', '三个月上岸的复习节奏（附时间表）｜踩坑实录（答疑整理）', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天4小时，其中资料分析固定55分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。', '备考', '["专业目录", "综合管理类", "岗位表", "面试"]', '[]', 573, 61, 0, 11169, '2026-05-06T08:09:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_111_949', 'cpu_政务_04', '考前一晚睡不着的解决办法（2025 年更新）（补充）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨4点还醒着，第二天资料分析基本是蒙的。', '备考', '["申论", "综合管理类"]', '[]', 647, 65, 39, 24571, '2026-06-20T23:22:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_112_467', 'cpu_政务_04', '在职备考怎么挤时间（第二篇）', '通勤路上听音频，午休做35道题，晚上留4小时集中攻一个模块。关键是别追求每天学很久，而是别断。我断过一周，回来手感全没了。以上仅是个人经历，具体以官方公告为准。', '备考', '["应届生", "综合管理类", "行测"]', '[]', 2119, 518, 101, 37059, '2026-06-02T07:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_113_455', 'cpu_pool_008', '资料分析提速的几个笨办法｜云台区', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了70天，从每题97秒降到55秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（23 届，一战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "综合管理类"]', '[]', 485, 46, 25, 16820, '2026-06-08T21:07:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_114_899', 'cpu_基层_11', '怎么分辨押题命中率的水分｜干货', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（写于笔试前 45 天。）转载请注明出处。', '备考', '["专业目录", "省考"]', '[]', 728, 187, 5, 20669, '2026-05-04T22:10:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_115_644', 'cpu_pool_016', '准考证打印那几天的注意事项｜踩坑实录', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打60份备用，考场丢了没地方补。', '备考', '["备考经验", "避坑"]', '[]', 151, 14, 0, 5893, '2026-07-07T19:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_116_732', 'cpu_公考_01', '资料分析提速的几个笨办法（续）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了58天，从每题81秒降到59秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（更新：进面了。）有问题评论区问，看到就回。', '备考', '["资格复审", "公务员", "省考", "申论"]', '[]', 0, 0, 1, 0, '2025-07-15T15:07:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_117_389', 'cpu_申论_02', '怎么分辨押题命中率的水分｜南岭省', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（我报的是 NL-14380，情况可能跟你不一样。）以上仅是个人经历，具体以官方公告为准。', '备考', '["避坑", "应届生", "面试"]', '[]', 935, 157, 5, 30227, '2026-05-09T11:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_118_548', 'cpu_应届_10', '专业名字带「数据」的到底能报哪些岗位（续）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2026年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。', '备考', '["避坑", "省考"]', '[]', 0, 0, 0, 0, '2026-06-13T07:32:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_119_228', 'cpu_公考_01', '资料分析提速的几个笨办法（第二篇）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了54天，从每题96秒降到53秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（写于笔试前 45 天。）', '备考', '["申论", "资格复审", "行测"]', '[]', 0, 0, 9, 0, '2026-06-12T18:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_120_426', 'cpu_上岸_00', '成绩复核申请是怎么回事｜在职考生视角', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后90个工作日内提交书面材料，过期不受理。（更新：弃考了。）有问题评论区问，看到就回。', '备考', '["公务员", "行测"]', '[]', 0, 0, 0, 0, '2026-06-05T11:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_121_355', 'cpu_pool_001', '资料分析提速的几个笨办法（2025 年更新）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了52天，从每题114秒降到64秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。', '备考', '["避坑", "综合管理类"]', '[]', 1057, 175, 56, 35035, '2026-06-04T19:04:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_122_838', 'cpu_上岸_00', '落榜之后我调整了两个月（第二篇）', '第一年差2.5分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。有问题评论区问，看到就回。', '备考', '["专业目录", "公务员"]', '[]', 452, 63, 59, 4691, '2026-06-27T17:20:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_123_266', 'cpu_云台_08', '有人卖面试内部名单，这事性质很严重｜数据治理岗', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（25 届，二战。）', '备考', '["综合管理类", "资格复审", "应届生"]', '[]', 0, 0, 25, 0, '2026-06-21T08:34:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_124_638', 'cpu_公考_01', '协议保过班到底靠不靠谱｜长文', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（评论区有 3 条追问我统一回在这里了。）以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "备考经验", "省考", "资格复审"]', '[]', 446, 110, 40, 8252, '2025-07-21T20:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_125_194', 'cpu_基层_11', '那些说有内部题的，我劝你别碰（更新版）', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。', '备考', '["应届生", "避坑", "省考"]', '[]', 98, 21, 31, 2455, '2026-07-07T22:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_126_182', 'cpu_云台_08', '专业名字带「数据」的到底能报哪些岗位（2025 年更新）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2026年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（更新：换岗位了。）', '备考', '["应届生", "综合管理类", "岗位表", "备考经验"]', '[]', 1298, 409, 0, 28989, '2025-07-21T12:10:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_127_673', 'cpu_基层_11', '落榜之后我调整了两个月｜在职考生视角', '第一年差7.3分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（更新：进面了。）', '备考', '["申论", "公务员", "应届生", "行测"]', '[]', 771, 59, 26, 15873, '2026-05-09T21:14:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_128_281', 'cpu_政务_04', '岗位表和补充公告不一致的时候听谁的｜二战总结', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。', '备考', '["资格复审", "面试", "申论"]', '[]', 0, 0, 36, 0, '2026-06-04T10:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_129_807', 'cpu_政务_04', '资料分析提速的几个笨办法（续）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了79天，从每题88秒降到53秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "行测"]', '[]', 0, 0, 0, 0, '2025-07-25T13:44:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_130_390', 'cpu_云台_08', '资料分析提速的几个笨办法（2024 年更新）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了89天，从每题84秒降到65秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。', '备考', '["省考", "面试"]', '[]', 269, 28, 40, 7813, '2025-07-25T09:53:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_131_742', 'cpu_政务_04', '岗位表和补充公告不一致的时候听谁的（续）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（更新：差几分。）以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "专业目录"]', '[]', 0, 0, 0, 0, '2025-07-26T14:19:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_132_788', 'cpu_云台_08', '专业目录读起来为什么这么费劲', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。（评论区有 25 条追问我统一回在这里了。）有问题评论区问，看到就回。', '备考', '["避坑", "资格复审", "备考经验", "申论"]', '[]', 1172, 224, 53, 7091, '2026-05-02T11:31:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_133_656', 'cpu_pool_017', '跟家里怎么沟通考公这件事｜踩坑实录', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。转载请注明出处。', '备考', '["避坑", "应届生", "备考经验"]', '[]', 700, 156, 15, 20440, '2026-05-25T12:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_134_556', 'cpu_pool_003', '落榜之后我调整了两个月｜慎入', '第一年差2.3分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（我报的是 NL-14477，情况可能跟你不一样。）有问题评论区问，看到就回。', '备考', '["省考", "资格复审", "避坑"]', '[]', 787, 77, 58, 17651, '2025-07-17T07:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_135_925', 'cpu_行测_03', '申论到底怎么提分（补充）', '找了老师批改50篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。（我报的是 NL-14119，情况可能跟你不一样。）', '备考', '["资格复审", "省考", "行测"]', '[]', 1292, 274, 27, 26975, '2025-07-14T17:56:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_136_726', 'cpu_行测_03', '落榜之后我调整了两个月（第二篇）', '第一年差2.8分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。不接广告，不推荐机构。', '备考', '["综合管理类", "省考", "资格复审"]', '[]', 1773, 555, 3, 68557, '2026-07-03T17:54:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_137_418', 'cpu_pool_005', '落榜之后我调整了两个月（2024 年更新）（更新版）', '第一年差0.6分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（25 届，二战。）后续有变化我再更新。', '备考', '["备考经验", "面试", "资格复审", "行测"]', '[]', 1291, 296, 23, 27233, '2025-07-21T09:49:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_138_252', 'cpu_备考_05', '成绩复核申请是怎么回事｜仅供参考', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后47个工作日内提交书面材料，过期不受理。（写于笔试前 25 天。）不接广告，不推荐机构。', '备考', '["公务员", "备考经验"]', '[]', 1498, 255, 26, 38311, '2026-06-06T07:21:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_139_220', 'cpu_云台_08', '考前一晚睡不着的解决办法（更新版）', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨3点还醒着，第二天资料分析基本是蒙的。不接广告，不推荐机构。', '备考', '["省考", "备考经验", "申论", "岗位表"]', '[]', 916, 206, 2, 35108, '2025-07-13T21:14:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_140_359', 'cpu_公考_01', '跟家里怎么沟通考公这件事｜慎入', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。（23 届，一战。）', '备考', '["岗位表", "面试", "应届生"]', '[]', 384, 23, 0, 12287, '2026-06-06T22:09:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_141_732', 'cpu_面试_07', '资料分析提速的几个笨办法｜综合管理类', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了87天，从每题83秒降到45秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（评论区有 13 条追问我统一回在这里了。）转载请注明出处。', '备考', '["备考经验", "申论"]', '[]', 0, 0, 0, 0, '2025-07-14T07:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_142_377', 'cpu_岗位_06', '落榜之后我调整了两个月｜二战总结', '第一年差0.5分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。', '备考', '["备考经验", "资格复审"]', '[]', 1286, 247, 8, 28389, '2026-05-12T11:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_143_931', 'cpu_公考_09', '相近专业能不能报，我踩过的坑｜云台区', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。不接广告，不推荐机构。', '备考', '["备考经验", "应届生"]', '[]', 1269, 381, 17, 39064, '2026-05-11T19:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_144_695', 'cpu_申论_02', '三个月上岸的复习节奏（附时间表）（更新版）', '我是8月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天6小时，其中资料分析固定32分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。', '备考', '["避坑", "备考经验"]', '[]', 0, 0, 0, 0, '2026-06-02T09:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_145_833', 'cpu_基层_11', '资料分析提速的几个笨办法（续）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了25天，从每题110秒降到56秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。后续有变化我再更新。', '备考', '["避坑", "行测"]', '[]', 2312, 135, 30, 77349, '2026-05-16T15:48:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_146_765', 'cpu_公考_01', '相近专业能不能报，我踩过的坑（补充）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（写于笔试前 53 天。）', '备考', '["行测", "岗位表", "应届生", "面试"]', '[]', 1444, 360, 40, 57475, '2026-06-07T10:49:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_147_441', 'cpu_云台_08', '成绩复核申请是怎么回事｜南岭省', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后74个工作日内提交书面材料，过期不受理。（更新：进面了。）以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "资格复审"]', '[]', 408, 91, 22, 4670, '2026-05-26T17:45:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_148_677', 'cpu_pool_025', '落榜之后我调整了两个月（2026 年更新）', '第一年差5.5分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。', '备考', '["岗位表", "面试", "专业目录", "避坑"]', '[]', 47, 3, 0, 1458, '2026-06-09T23:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_149_287', 'cpu_申论_02', '机构说相近专业都能报，可信吗（更新版）', '不可信。机构没有资格认定权，说了不作数。他们这么说是为了扩大招生面。以官方目录和招录单位书面答复为准，其他都是参考。（更新：差几分。）转载请注明出处。', '备考', '["面试", "岗位表", "行测"]', '[]', 0, 0, 0, 0, '2026-06-18T23:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_150_563', 'cpu_pool_007', '有人卖面试内部名单，这事性质很严重', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（更新：已上岸。）后续有变化我再更新。', '备考', '["应届生", "行测", "避坑", "专业目录"]', '[]', 0, 0, 17, 0, '2026-06-02T20:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_151_787', 'cpu_上岸_00', '在职备考怎么挤时间｜数据治理岗', '通勤路上听音频，午休做35道题，晚上留1小时集中攻一个模块。关键是别追求每天学很久，而是别断。我断过一周，回来手感全没了。不接广告，不推荐机构。', '备考', '["岗位表", "省考", "备考经验", "避坑"]', '[]', 291, 66, 0, 7485, '2026-05-08T11:46:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_152_474', 'cpu_pool_013', '资料分析提速的几个笨办法（答疑整理）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了51天，从每题91秒降到53秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（我报的是 NL-14380，情况可能跟你不一样。）转载请注明出处。', '备考', '["避坑", "备考经验", "应届生", "申论"]', '[]', 169, 56, 64, 2138, '2025-07-10T21:14:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_153_586', 'cpu_行测_03', '考点提前踩点的几个建议（续）', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2023年就吃过这个亏，差点迟到。（写于笔试前 83 天。）不接广告，不推荐机构。', '备考', '["资格复审", "申论", "行测", "专业目录"]', '[]', 180, 31, 24, 3727, '2026-06-11T19:26:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_154_843', 'cpu_云台_08', '考点提前踩点的几个建议（补充）', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2025年就吃过这个亏，差点迟到。', '备考', '["省考", "行测", "申论"]', '[]', 872, 132, 58, 17807, '2026-07-01T17:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_155_402', 'cpu_备考_05', '考场能带什么不能带什么（2024 年更新）', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。不接广告，不推荐机构。', '备考', '["专业目录", "备考经验", "公务员", "资格复审"]', '[]', 1146, 361, 59, 14032, '2025-07-17T11:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_156_832', 'cpu_pool_017', '资料分析提速的几个笨办法（第二篇）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了76天，从每题84秒降到55秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（评论区有 24 条追问我统一回在这里了。）', '备考', '["省考", "避坑"]', '[]', 1312, 318, 30, 46635, '2026-05-22T12:30:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_157_574', 'cpu_公考_01', '毕业季和备考撞在一起怎么办（更新版）', '答辩、实习、离校手续、考试全挤在7月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。后续有变化我再更新。', '备考', '["专业目录", "避坑"]', '[]', 540, 156, 18, 6374, '2026-06-20T10:03:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_158_711', 'cpu_上岸_00', '专业名字带「数据」的到底能报哪些岗位｜踩坑实录（续）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2025年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（更新：进面了。）后续有变化我再更新。', '备考', '["资格复审", "行测", "避坑"]', '[]', 0, 0, 67, 0, '2026-06-18T21:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_159_665', 'cpu_公考_01', '毕业季和备考撞在一起怎么办（2025 年更新）（第二篇）', '答辩、实习、离校手续、考试全挤在8月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（我报的是 NL-14356，情况可能跟你不一样。）不接广告，不推荐机构。', '备考', '["行测", "专业目录"]', '[]', 2054, 609, 13, 46098, '2026-06-25T19:57:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_160_961', 'cpu_政务_04', '资格复审要准备的材料清单｜云台区', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的3个月期限差点不够用。（写于笔试前 13 天。）后续有变化我再更新。', '备考', '["行测", "公务员", "专业目录"]', '[]', 312, 79, 71, 7907, '2025-07-20T07:39:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_161_879', 'cpu_应届_10', '考前一晚睡不着的解决办法｜上岸后回看', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨1点还醒着，第二天资料分析基本是蒙的。（写于笔试前 16 天。）', '备考', '["申论", "行测", "岗位表", "综合管理类"]', '[]', 0, 0, 31, 0, '2026-06-17T09:07:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_162_159', 'cpu_应届_10', '相近专业能不能报，我踩过的坑｜数据治理岗（更新版）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（写于笔试前 11 天。）转载请注明出处。', '备考', '["应届生", "公务员"]', '[]', 1332, 333, 0, 49633, '2026-05-15T10:10:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_163_869', 'cpu_公考_09', '落榜之后我调整了两个月（更新版）', '第一年差0.6分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。（评论区有 18 条追问我统一回在这里了。）不接广告，不推荐机构。', '备考', '["面试", "公务员", "应届生"]', '[]', 916, 130, 11, 31934, '2026-06-11T16:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_164_357', 'cpu_备考_05', '跟家里怎么沟通考公这件事', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。', '备考', '["行测", "避坑", "岗位表"]', '[]', 813, 207, 23, 10245, '2026-05-08T15:32:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_165_463', 'cpu_应届_10', '岗位表和补充公告不一致的时候听谁的｜干货', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（23 届，一战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["行测", "综合管理类", "备考经验"]', '[]', 209, 47, 18, 2144, '2026-05-15T22:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_166_160', 'cpu_云台_08', '相近专业能不能报，我踩过的坑｜干货', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。以上仅是个人经历，具体以官方公告为准。', '备考', '["行测", "公务员", "申论", "备考经验"]', '[]', 1486, 259, 54, 38028, '2026-05-22T20:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_167_384', 'cpu_基层_11', '准考证打印那几天的注意事项', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打55份备用，考场丢了没地方补。', '备考', '["省考", "备考经验", "避坑", "行测"]', '[]', 616, 192, 27, 5533, '2026-07-07T15:47:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_168_499', 'cpu_岗位_06', '资料分析提速的几个笨办法｜应届生视角', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了38天，从每题101秒降到44秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（评论区有 17 条追问我统一回在这里了。）', '备考', '["面试", "公务员", "行测", "资格复审"]', '[]', 292, 44, 23, 10395, '2026-07-06T20:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_169_647', 'cpu_应届_10', '资料分析提速的几个笨办法（2026 年更新）（更新版）', '别一上来就学秒杀公式，先把首数法和特征数字背熟。我练了79天，从每题73秒降到58秒。另外速算不是万能的，遇到复杂的老老实实算比蒙对的期望高。（写于笔试前 24 天。）', '备考', '["岗位表", "综合管理类"]', '[]', 605, 109, 32, 22129, '2026-06-09T23:17:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_170_782', 'cpu_岗位_06', '怎么分辨押题命中率的水分（2024 年更新）', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（更新：已上岸。）', '备考', '["综合管理类", "岗位表", "面试", "应届生"]', '[]', 1676, 396, 69, 38964, '2026-06-17T14:26:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_171_683', 'cpu_云台_08', '岗位表和补充公告不一致的时候听谁的（续）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（更新：差几分。）不接广告，不推荐机构。', '备考', '["综合管理类", "行测", "申论"]', '[]', 119, 13, 0, 1989, '2026-06-28T20:54:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_172_787', 'cpu_应届_10', '跟家里怎么沟通考公这件事｜仅供参考', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。（写于笔试前 16 天。）转载请注明出处。', '备考', '["资格复审", "申论", "综合管理类", "面试"]', '[]', 784, 214, 1, 25389, '2026-06-22T12:13:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_173_625', 'cpu_申论_02', '成绩复核申请是怎么回事（续）', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后84个工作日内提交书面材料，过期不受理。有问题评论区问，看到就回。', '备考', '["应届生", "面试"]', '[]', 847, 50, 6, 14455, '2026-06-09T15:44:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_174_791', 'cpu_面试_07', '专业名字带「数据」的到底能报哪些岗位｜上岸后回看', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2024年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（评论区有 9 条追问我统一回在这里了。）', '备考', '["省考", "行测", "公务员", "避坑"]', '[]', 468, 28, 0, 7824, '2026-06-10T20:41:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_175_115', 'cpu_应届_10', '在职备考怎么挤时间（2026 年更新）', '通勤路上听音频，午休做31道题，晚上留1小时集中攻一个模块。关键是别追求每天学很久，而是别断。我断过一周，回来手感全没了。（我报的是 NL-14356，情况可能跟你不一样。）后续有变化我再更新。', '备考', '["综合管理类", "申论"]', '[]', 490, 116, 31, 11925, '2025-07-23T16:39:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_176_642', 'cpu_应届_10', '专业目录读起来为什么这么费劲｜长文', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。（23 届，二战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["公务员", "专业目录", "资格复审"]', '[]', 629, 199, 0, 12752, '2026-06-04T09:26:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_177_124', 'cpu_应届_10', '机构说相近专业都能报，可信吗｜综合管理类', '不可信。机构没有资格认定权，说了不作数。他们这么说是为了扩大招生面。以官方目录和招录单位书面答复为准，其他都是参考。（写于笔试前 15 天。）转载请注明出处。', '备考', '["专业目录", "申论", "面试", "备考经验"]', '[]', 35, 6, 66, 440, '2026-06-26T08:11:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_178_592', 'cpu_云台_08', '跟家里怎么沟通考公这件事｜踩坑实录（更新版）', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。（我报的是 NL-14263，情况可能跟你不一样。）', '备考', '["备考经验", "综合管理类"]', '[]', 0, 0, 20, 0, '2026-06-03T14:56:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_179_186', 'cpu_行测_03', '成绩复核申请是怎么回事｜应届生视角', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后22个工作日内提交书面材料，过期不受理。（我报的是 NL-14308，情况可能跟你不一样。）', '备考', '["公务员", "应届生", "避坑", "申论"]', '[]', 732, 45, 11, 28022, '2026-07-01T23:59:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_180_178', 'cpu_pool_020', '三个月上岸的复习节奏（附时间表）｜仅供参考', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天4小时，其中资料分析固定44分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（评论区有 6 条追问我统一回在这里了。）有问题评论区问，看到就回。', '备考', '["行测", "面试", "综合管理类"]', '[]', 0, 0, 0, 0, '2026-06-13T22:38:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_181_410', 'cpu_pool_024', '成绩复核申请是怎么回事｜仅供参考（更新版）', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后34个工作日内提交书面材料，过期不受理。', '备考', '["面试", "公务员", "备考经验", "资格复审"]', '[]', 0, 0, 31, 0, '2026-06-10T19:54:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_182_202', 'cpu_行测_03', '考场能带什么不能带什么｜南岭省', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。后续有变化我再更新。', '备考', '["面试", "备考经验", "公务员", "应届生"]', '[]', 1085, 189, 12, 35739, '2026-07-05T18:17:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_183_814', 'cpu_pool_023', '怎么分辨押题命中率的水分（答疑整理）', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。不接广告，不推荐机构。', '备考', '["避坑", "岗位表", "应届生", "行测"]', '[]', 1111, 330, 5, 9430, '2026-05-15T22:12:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_184_564', 'cpu_面试_07', '三个月上岸的复习节奏（附时间表）（答疑整理）', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天10小时，其中资料分析固定36分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（26 届，一战。）以上仅是个人经历，具体以官方公告为准。', '备考', '["备考经验", "省考", "综合管理类", "申论"]', '[]', 0, 0, 0, 0, '2026-05-28T10:04:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_185_381', 'cpu_pool_020', '岗位表和补充公告不一致的时候听谁的（第二篇）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（评论区有 4 条追问我统一回在这里了。）', '备考', '["面试", "行测", "省考", "避坑"]', '[]', 790, 224, 0, 21613, '2026-06-19T16:09:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_186_126', 'cpu_面试_07', '申论到底怎么提分（2026 年更新）', '找了老师批改9篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。（写于笔试前 58 天。）', '备考', '["省考", "备考经验"]', '[]', 0, 0, 54, 0, '2026-05-03T08:14:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_187_100', 'cpu_面试_07', '落榜之后我调整了两个月｜长文（续）', '第一年差3.3分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。', '备考', '["综合管理类", "行测", "公务员", "避坑"]', '[]', 0, 0, 0, 0, '2025-07-25T08:47:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_188_816', 'cpu_申论_02', '有人卖面试内部名单，这事性质很严重｜踩坑实录', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（我报的是 NL-14356，情况可能跟你不一样。）', '备考', '["行测", "资格复审", "备考经验"]', '[]', 1513, 145, 50, 59848, '2026-06-10T21:05:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_189_138', 'cpu_行测_03', '考点提前踩点的几个建议｜上岸后回看', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2024年就吃过这个亏，差点迟到。不接广告，不推荐机构。', '备考', '["省考", "资格复审", "综合管理类", "应届生"]', '[]', 2328, 178, 86, 14811, '2026-06-17T23:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_190_878', 'cpu_pool_013', '怎么分辨押题命中率的水分（更新版）', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。', '备考', '["综合管理类", "应届生", "岗位表", "避坑"]', '[]', 62, 21, 22, 1971, '2025-07-25T08:48:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_191_379', 'cpu_面试_07', '考场能带什么不能带什么（2024 年更新）（第二篇）', '2B 铅笔、黑色签字笔、橡皮、直尺可以带；计算器、涂改液、智能手表不行。手机要关机放在考场外指定位置，被发现在身上就是违纪。矿泉水一般可以但要撕掉标签。（我报的是 NL-14401，情况可能跟你不一样。）转载请注明出处。', '备考', '["申论", "备考经验", "应届生"]', '[]', 438, 151, 47, 3597, '2025-07-18T15:46:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_192_235', 'cpu_pool_015', '相近专业能不能报，我踩过的坑（更新版）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（写于笔试前 2 天。）有问题评论区问，看到就回。', '备考', '["面试", "公务员", "行测"]', '[]', 1801, 266, 35, 12014, '2025-07-24T21:50:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_193_515', 'cpu_上岸_00', '三个月上岸的复习节奏（附时间表）（答疑整理）', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天7小时，其中资料分析固定42分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（更新：差几分。）转载请注明出处。', '备考', '["省考", "面试", "备考经验", "资格复审"]', '[]', 530, 41, 26, 11720, '2026-06-18T22:53:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_194_387', 'cpu_pool_018', '跟家里怎么沟通考公这件事（2024 年更新）', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。（写于笔试前 51 天。）', '备考', '["申论", "省考", "综合管理类"]', '[]', 1273, 251, 21, 8999, '2026-06-08T22:35:00+08:00');
