INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_198_718', 'cpu_岗位_06', '岗位表和补充公告不一致的时候听谁的｜云台区（补充）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。后续有变化我再更新。', '备考', '["省考", "行测", "应届生"]', '[]', 1322, 228, 0, 17139, '2025-07-08T09:37:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_199_749', 'cpu_上岸_00', '怎么分辨押题命中率的水分｜应届生视角（答疑整理）', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（更新：已上岸。）', '备考', '["资格复审", "避坑"]', '[]', 546, 119, 16, 8349, '2025-07-10T18:39:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_200_668', 'cpu_基层_11', '协议保过班到底靠不靠谱｜南岭省（补充）', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（我报的是 NL-14308，情况可能跟你不一样。）以上仅是个人经历，具体以官方公告为准。', '备考', '["资格复审", "避坑"]', '[]', 1249, 81, 0, 30372, '2026-05-24T23:55:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_201_971', 'cpu_政务_04', '毕业季和备考撞在一起怎么办（补充）', '答辩、实习、离校手续、考试全挤在6月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。', '备考', '["省考", "申论", "备考经验"]', '[]', 715, 69, 61, 17996, '2026-06-08T19:09:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_202_759', 'cpu_上岸_00', '岗位表和补充公告不一致的时候听谁的（答疑整理）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。（评论区有 15 条追问我统一回在这里了。）', '备考', '["公务员", "专业目录", "岗位表", "申论"]', '[]', 875, 51, 0, 15976, '2026-05-26T07:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_203_947', 'cpu_公考_09', '协议保过班到底靠不靠谱｜数据治理岗', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。后续有变化我再更新。', '备考', '["专业目录", "行测", "公务员"]', '[]', 1754, 188, 0, 60477, '2026-06-25T10:35:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_204_563', 'cpu_上岸_00', '专业目录读起来为什么这么费劲（续）', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。（更新：差几分。）以上仅是个人经历，具体以官方公告为准。', '备考', '["面试", "资格复审"]', '[]', 1413, 239, 54, 24950, '2026-06-16T23:11:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_205_556', 'cpu_应届_10', '协议保过班到底靠不靠谱（2024 年更新）（答疑整理）', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（26 届，二战。）', '备考', '["专业目录", "备考经验", "综合管理类"]', '[]', 0, 0, 0, 0, '2025-07-12T19:07:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_206_487', 'cpu_公考_01', '跟家里怎么沟通考公这件事｜综合管理类', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。', '备考', '["岗位表", "避坑"]', '[]', 788, 77, 0, 22805, '2025-07-13T14:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_207_630', 'cpu_基层_11', '毕业季和备考撞在一起怎么办（2025 年更新）（补充）', '答辩、实习、离校手续、考试全挤在5月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（25 届，三战。）', '备考', '["综合管理类", "应届生", "面试", "省考"]', '[]', 125, 12, 10, 2998, '2026-07-06T19:11:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_208_516', 'cpu_备考_05', '准考证打印那几天的注意事项（2024 年更新）', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打18份备用，考场丢了没地方补。（我报的是 NL-14401，情况可能跟你不一样。）', '备考', '["行测", "备考经验", "岗位表"]', '[]', 752, 181, 0, 12819, '2026-06-15T07:48:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_209_503', 'cpu_面试_07', '成绩复核申请是怎么回事｜南岭省（第二篇）', '只查漏评和加分错误，不重新评主观题。也就是说申论觉得给低了没法申诉。申请要在成绩公布后40个工作日内提交书面材料，过期不受理。（写于笔试前 59 天。）转载请注明出处。', '备考', '["申论", "省考", "应届生", "综合管理类"]', '[]', 2071, 202, 49, 43219, '2026-06-22T10:54:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_210_814', 'cpu_pool_019', '模考成绩波动大是正常的吗（续）', '正常。我模考分数从121到145都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。', '备考', '["综合管理类", "资格复审", "行测", "面试"]', '[]', 1277, 250, 44, 14322, '2025-07-17T08:02:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_211_207', 'cpu_pool_011', '专业名字带「数据」的到底能报哪些岗位（更新版）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2025年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（写于笔试前 5 天。）后续有变化我再更新。', '备考', '["专业目录", "岗位表"]', '[]', 694, 78, 8, 11034, '2026-06-18T13:09:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_212_720', 'cpu_pool_000', '三个月上岸的复习节奏（附时间表）（2024 年更新）（续）', '我是5月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天9小时，其中资料分析固定55分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（更新：弃考了。）转载请注明出处。', '备考', '["备考经验", "避坑"]', '[]', 660, 157, 77, 13837, '2026-07-04T07:52:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_213_626', 'cpu_公考_09', '落榜之后我调整了两个月｜综合管理类', '第一年差8.0分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。转载请注明出处。', '备考', '["专业目录", "行测"]', '[]', 155, 8, 77, 5995, '2026-06-19T17:20:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_214_233', 'cpu_公考_01', '专业目录读起来为什么这么费劲｜踩坑实录', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。', '备考', '["岗位表", "应届生"]', '[]', 2525, 832, 60, 71829, '2026-06-21T09:47:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_215_235', 'cpu_应届_10', '相近专业能不能报，我踩过的坑（第二篇）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（我报的是 NL-14356，情况可能跟你不一样。）后续有变化我再更新。', '备考', '["公务员", "行测", "岗位表"]', '[]', 1100, 217, 40, 42276, '2025-07-11T23:19:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_216_555', 'cpu_面试_07', '专业目录读起来为什么这么费劲（续）', '目录本身是分级的，编号一层套一层，岗位表上写的有时候是上面那级、有时候是下面那级。我一开始压根没注意到这个区别，看着差不多就以为是一回事。具体每一级各自管到哪儿，还是得对着当年的正式文件一条条看，我说不好。有问题评论区问，看到就回。', '备考', '["公务员", "避坑"]', '[]', 600, 120, 0, 18833, '2025-07-21T18:15:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_217_763', 'cpu_基层_11', '有人卖面试内部名单，这事性质很严重（2026 年更新）（第二篇）', '这不只是骗钱的问题，涉及公民个人信息。买卖考生名单是违法的，而且拿到名单对你面试没有任何帮助，面试是当场抽签当场答。别为了所谓信息差搭进去。（写于笔试前 42 天。）以上仅是个人经历，具体以官方公告为准。', '备考', '["岗位表", "应届生", "行测", "申论"]', '[]', 0, 0, 37, 0, '2025-07-23T19:34:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_218_993', 'cpu_行测_03', '模考成绩波动大是正常的吗｜在职考生视角', '正常。我模考分数从116到134都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。（我报的是 NL-14401，情况可能跟你不一样。）', '备考', '["岗位表", "面试", "综合管理类"]', '[]', 0, 0, 34, 0, '2026-06-19T21:45:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_219_459', 'cpu_云台_08', '申论到底怎么提分｜综合管理类', '找了老师批改44篇之后才明白，申论扣分大头不是文采，是没踩到采分点。归纳概括题就老老实实抄材料关键词，别自己组织语言。文章论述要先把论点摆清楚。转载请注明出处。', '备考', '["公务员", "应届生"]', '[]', 813, 257, 32, 28139, '2026-07-01T08:48:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_220_509', 'cpu_pool_009', '毕业季和备考撞在一起怎么办（答疑整理）', '答辩、实习、离校手续、考试全挤在4月。我的做法是先把有硬截止的事排进日历，复习填空隙。答辩前三天完全不碰行测，答辩完再回来，损失比硬撑小。（更新：差几分。）转载请注明出处。', '备考', '["避坑", "省考", "行测", "公务员"]', '[]', 1470, 120, 3, 15378, '2025-07-10T17:21:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_221_256', 'cpu_公考_09', '协议保过班到底靠不靠谱（补充）', '关键看退费条款怎么写。正规的会写清楚：未达到什么分数、退多少比例、什么时候退、扣哪些费用。有问题的会含糊其辞，或者把「进面」定义得很宽。签之前把合同附件逐条看完，别只听销售说。（写于笔试前 81 天。）不接广告，不推荐机构。', '备考', '["面试", "资格复审", "岗位表"]', '[]', 1627, 105, 0, 17509, '2025-07-12T16:50:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_222_940', 'cpu_pool_022', '准考证打印那几天的注意事项（续）', '系统在开放头两天最卡，建议错峰。打印前核对姓名、身份证号和考点地址，有错误要在打印期内联系考区改，考完就来不及了。多打47份备用，考场丢了没地方补。（我报的是 NL-14401，情况可能跟你不一样。）转载请注明出处。', '备考', '["应届生", "申论", "综合管理类"]', '[]', 0, 0, 41, 0, '2026-05-09T20:42:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_223_882', 'cpu_云台_08', '那些说有内部题的，我劝你别碰｜上岸后回看（第二篇）', '考前总有人加你微信说有内部渠道的真题，几百块一份。先不说是不是骗钱，就算真的，买了就是违纪，查出来取消成绩记诚信档案。而且我买过一次（后悔），所谓密卷跟网上免费的模拟题重合度极高。', '备考', '["申论", "岗位表", "公务员"]', '[]', 0, 0, 76, 0, '2026-05-03T23:29:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_224_208', 'cpu_云台_08', '考点提前踩点的几个建议｜上岸后回看（第二篇）', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2024年就吃过这个亏，差点迟到。（我报的是 NL-14401，情况可能跟你不一样。）以上仅是个人经历，具体以官方公告为准。', '备考', '["避坑", "专业目录", "公务员"]', '[]', 1133, 392, 25, 23630, '2026-06-18T07:54:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_225_744', 'cpu_pool_007', '相近专业能不能报，我踩过的坑（第二篇）', '培训机构的老师跟我说「一般都能报」，我信了，结果资格审查没过。后来才知道认定权在招录单位，机构说了不算。而且不同单位口径可能不一样，同一个专业在 A 单位过了 B 单位不一定过。血泪教训：一定要书面咨询，口头答复没用。（26 届，三战。）', '备考', '["面试", "避坑", "备考经验", "岗位表"]', '[]', 1150, 213, 28, 28941, '2026-06-27T20:51:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_226_794', 'cpu_pool_005', '三个月上岸的复习节奏（附时间表）｜综合管理类', '我是4月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天5小时，其中资料分析固定60分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（评论区有 18 条追问我统一回在这里了。）', '备考', '["行测", "岗位表"]', '[]', 0, 0, 67, 0, '2025-07-09T19:01:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_227_225', 'cpu_申论_02', '资格复审要准备的材料清单｜南岭省', '身份证、毕业证或学生证、成绩单、就业推荐表、学信网在线验证报告。验证报告要注意有效期，必须覆盖复审当天，我第一次申请的1个月期限差点不够用。（更新：弃考了。）后续有变化我再更新。', '备考', '["专业目录", "公务员", "综合管理类"]', '[]', 596, 51, 12, 8200, '2026-06-15T11:34:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_228_722', 'cpu_应届_10', '专业名字带「数据」的到底能报哪些岗位（续）', '这问题我在群里问过好几轮，答案五花八门。有人说只看大类就行，有人说卡得很死，还有人说各单位口径都不一样。我翻了2026年的岗位表，光带「数据」字样的写法就有好几种，看着确实不像一回事，但具体怎么算我也没搞清。别信我，也别信群里的，自己去查当年的正式目录，再发邮件问招录单位，把答复留好。（写于笔试前 9 天。）后续有变化我再更新。', '备考', '["资格复审", "应届生", "专业目录"]', '[]', 891, 83, 54, 21778, '2025-07-27T17:27:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_229_538', 'cpu_公考_01', '考前一晚睡不着的解决办法｜仅供参考', '别在考前一晚改作息，白天正常活动累一点自然就困了。我考前喝了咖啡结果凌晨2点还醒着，第二天资料分析基本是蒙的。（我报的是 NL-14477，情况可能跟你不一样。）有问题评论区问，看到就回。', '备考', '["应届生", "面试", "资格复审"]', '[]', 177, 31, 18, 2057, '2026-06-10T18:18:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_230_647', 'cpu_基层_11', '岗位表和补充公告不一致的时候听谁的（续）', '遇到过一次，岗位表写得宽，报名中途出了补充公告把范围缩窄了。当时群里吵翻了，有说信赖利益的，有说该改报的。后来问了考试院，答复是补充公告在报名截止前发布的就以补充公告为准，已缴费的可以改报或者退费。所以报名期间要盯着公告页，别报完就不看了。', '备考', '["资格复审", "面试", "公务员"]', '[]', 0, 0, 15, 0, '2025-07-08T23:30:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_231_862', 'cpu_面试_07', '三个月上岸的复习节奏（附时间表）（更新版）', '我是7月开始的，前六周打基础，中间四周刷套题，最后两周只做错题和模考。每天8小时，其中资料分析固定26分钟。不建议一开始就刷套题，基础不牢做套题就是浪费卷子。（写于笔试前 30 天。）后续有变化我再更新。', '备考', '["备考经验", "公务员", "面试", "专业目录"]', '[]', 0, 0, 5, 0, '2026-06-19T20:07:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_232_551', 'cpu_应届_10', '怎么分辨押题命中率的水分（补充）', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（25 届，二战。）', '备考', '["专业目录", "备考经验", "资格复审"]', '[]', 1166, 341, 61, 8575, '2026-07-01T11:16:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_233_221', 'cpu_pool_020', '落榜之后我调整了两个月（更新版）', '第一年差5.5分没进面，那段时间挺难受的。后来想明白了，一次考试定不了什么，把复盘做完该干嘛干嘛。第二年上了。', '备考', '["避坑", "申论", "专业目录"]', '[]', 947, 236, 60, 9103, '2026-06-21T09:27:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_234_918', 'cpu_公考_09', '模考成绩波动大是正常的吗（补充）', '正常。我模考分数从125到133都有，主要看题目难度和当天状态。别因为一次考砸就换资料换方法，那样更乱。看趋势不看单次。（评论区有 4 条追问我统一回在这里了。）', '备考', '["应届生", "岗位表"]', '[]', 2229, 556, 34, 21475, '2026-06-21T22:06:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_235_531', 'cpu_公考_09', '跟家里怎么沟通考公这件事（补充）', '父母催得紧的时候压力很大。我的经验是把进度可视化给他们看，比如做了多少题、模考多少分，比空口说「在努力」有用。', '备考', '["专业目录", "省考"]', '[]', 588, 193, 21, 13975, '2026-05-08T21:36:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_236_164', 'cpu_pool_024', '考点提前踩点的几个建议｜云台区', '别等到考试当天才第一次去。大一点的考点常常有好几个入口，走错了绕一圈可能要十几分钟，准考证上写哪个入口就走哪个。另外城里施工多，出门前查一下路况，我2025年就吃过这个亏，差点迟到。（24 届，三战。）后续有变化我再更新。', '备考', '["行测", "应届生"]', '[]', 1315, 344, 32, 43813, '2026-05-06T22:40:00+08:00');
INSERT INTO notes (note_id, author_id, title, body, category, tags, image_captions, like_count, collect_count, comment_count, view_count, published_at) VALUES ('cp_note_237_960', 'cpu_公考_01', '怎么分辨押题命中率的水分｜踩坑实录', '很多机构说命中率八成，仔细看是拿往年公开真题事后统计的，跟预测今年没关系。真正合规的资料会写明「基于公开真题的考点分布统计，不代表预知本年度试题」。（写于笔试前 64 天。）', '备考', '["岗位表", "综合管理类", "申论"]', '[]', 0, 0, 44, 0, '2026-07-03T17:17:00+08:00');
